#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int minimumTime(int n, std::vector<std::vector<int>>& relations, std::vector<int>& time) {
        std::vector<std::vector<int>> adj(n + 1);
        std::vector<int> inDegree(n + 1, 0);
        for (const auto& r : relations) {
            adj[r[0]].push_back(r[1]);
            inDegree[r[1]]++;
        }

        std::vector<int> dist(n + 1, 0);
        std::queue<int> q;
        for (int i = 1; i <= n; ++i) {
            if (inDegree[i] == 0) {
                dist[i] = time[i - 1];
                q.push(i);
            }
        }

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            for (int nxt : adj[curr]) {
                dist[nxt] = std::max(dist[nxt], dist[curr] + time[nxt - 1]);
                if (--inDegree[nxt] == 0) {
                    q.push(nxt);
                }
            }
        }

        return *std::max_element(dist.begin() + 1, dist.end());
    }
};

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

class Solution {
    public int minimumTime(int n, int[][] relations, int[] time) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[n + 1];
        for (int[] r : relations) {
            adj.get(r[0]).add(r[1]);
            inDegree[r[1]]++;
        }

        int[] dist = new int[n + 1];
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (inDegree[i] == 0) {
                dist[i] = time[i - 1];
                q.offer(i);
            }
        }

        while (!q.isEmpty()) {
            int curr = q.poll();
            for (int nxt : adj.get(curr)) {
                dist[nxt] = Math.max(dist[nxt], dist[curr] + time[nxt - 1]);
                if (--inDegree[nxt] == 0) {
                    q.offer(nxt);
                }
            }
        }

        int max = 0;
        for (int i = 1; i <= n; i++) {
            max = Math.max(max, dist[i]);
        }
        return max;
    }
}

/**
 * @param {number} n
 * @param {number[][]} relations
 * @param {number[]} time
 * @return {number}
 */
var minimumTime = function(n, relations, time) {
    const adj = Array.from({ length: n + 1 }, () => []);
    const inDegree = new Array(n + 1).fill(0);
    for (const [u, v] of relations) {
        adj[u].push(v);
        inDegree[v]++;
    }

    const dist = new Array(n + 1).fill(0);
    const q = [];
    for (let i = 1; i <= n; i++) {
        if (inDegree[i] === 0) {
            dist[i] = time[i - 1];
            q.push(i);
        }
    }

    let head = 0;
    while (head < q.length) {
        const curr = q[head++];
        for (const nxt of adj[curr]) {
            dist[nxt] = Math.max(dist[nxt], dist[curr] + time[nxt - 1]);
            inDegree[nxt]--;
            if (inDegree[nxt] === 0) {
                q.push(nxt);
            }
        }
    }

    let ans = 0;
    for (let i = 1; i <= n; i++) {
        ans = Math.max(ans, dist[i]);
    }
    return ans;
};
